static void 창자리그리기(int 가로,int Вертикаль_позиция,int 폭,int длина_ЗНАЧЕН,Терминал *Окно){
    int 왼쪽=가로>(int)Окно->координата_X?가로:(int)Окно->координата_X;
    int 위쪽=Вертикаль_позиция>(int)Окно->Y_координата?Вертикаль_позиция:(int)Окно->Y_координата;
    int право=가로+폭<(int)(Окно->координата_X+Окно->너비)?가로+폭:(int)(Окно->координата_X+Окно->너비);
    int 아래쪽=Вертикаль_позиция+длина_ЗНАЧЕН<(int)(Окно->Y_координата+Окно->높이)?Вертикаль_позиция+длина_ЗНАЧЕН:(int)(Окно->Y_координата+Окно->높이);
    Paint_регион(Окно->координата_X,Окно->Y_координата,Окно->너비,Окно->높이);
    if(왼쪽>=право||위쪽>=아래쪽){Paint_регион(가로,Вертикаль_позиция,폭,длина_ЗНАЧЕН);return;}
    Paint_регион(가로,Вертикаль_позиция,폭,위쪽-Вертикаль_позиция);
    Paint_регион(가로,아래쪽,폭,Вертикаль_позиция+длина_ЗНАЧЕН-아래쪽);
    Paint_регион(가로,위쪽,왼쪽-가로,아래쪽-위쪽);
    Paint_регион(право,위쪽,가로+폭-право,아래쪽-위쪽);
}
